const links=[...document.querySelectorAll(".mobile-dock a")];const sections=links.map(link=>document.querySelector(link.hash)).filter(Boolean);function updateDock(){const marker=window.innerHeight*.35;let current=sections[0];for(const section of sections){if(section.getBoundingClientRect().top<=marker)current=section}for(const link of links){if(link.hash===`#${current?.id}`)link.setAttribute("aria-current","location");else link.removeAttribute("aria-current")}}let pending=false;window.addEventListener("scroll",()=>{if(pending)return;pending=true;requestAnimationFrame(()=>{updateDock();pending=false})},{passive:true});window.addEventListener("resize",updateDock);updateDock();
